async function rebuild(reset=false){const token=++simulationToken,wasPlaying=playing,old=time;playing=false;ready=false;$('busy').style.display='flex';$('error').textContent='';$('restart').disabled=true;try{let next=await F.cached('combined');if(!next){next=new F.Model({cartCount:2});window.CART_BUILD=next;await next.run(()=>{$('progress').value=next.inspected;$('busyText').textContent=next.inspected.toLocaleString('en-US')+' / '+next.totalInput.toLocaleString('en-US')+' inspected · '+next.delivered+' pallets delivered · cycle '+next.headCycles+' · '+Math.floor(next.env.now)+' s'},()=>token!==simulationToken);}if(token!==simulationToken)return;model=next;makeActors();ready=true;time=reset?0:Math.min(old,model.total);$('time').max=model.total;$('bph').textContent=Math.round(model.bph).toLocaleString('en-US');$('pph').textContent=model.pph.toFixed(2);$('modelNotice').textContent=model.completeInput?'2 consecutive kiln carts · 18 active pallet wells · 4 AMRs · 4 product bays':'Replay stopped before completing the configured feed';renderAt(time);$('busy').style.display='none';playing=wasPlaying;window.CART_DEMO={model,scene,camera,renderer,seek:t=>{time=Math.min(model.total,Math.max(0,t));renderAt(time)},view,rebuild,showEquipment,requests};}catch(e){$('error').textContent=e.stack||e.message;window.CART_ERROR=e.stack||e.message;console.error(e)}finally{$('restart').disabled=false;lastWall=performance.now()}}
